<div class="footnote"><p><a name="Footnote_97_97" id="Footnote_97_97"></a><a href="#FNanchor_97_97"><span class="label">[97]</span></a> <i>The Lily</i> was a temperance paper started in Seneca
Falls, N. Y., in 1849. It was owned and edited by Mrs. Amelia Bloomer.
Though starting as the organ of a society, it soon became her
individual property. She carried it successfully six years, her
subscription list reaching 4,000. It was as pronounced on woman's
rights as temperance, and did good service in both reforms. We are
indebted to <i>The Lily</i> for most of our facts on the temperance
movement in New York.</p></div>

