<div class="footnote"><p><a name="Footnote_124_124" id="Footnote_124_124"></a><a href="#FNanchor_124_124"><span class="label">[124]</span></a> Mr. Hopkins further stated that, tenancy by the
courtesy operates in favor of the husband, not of the wife. It is the
husband's right during his life to the use of the wife's real estate
from her death, in case of a child or children born of the marriage.
It is defeasible now by the wife's will.&mdash;Cow. Rep. 74, 2 K. S., 4th
Ed. 331. Tenancy by right of dower is the wife's right during her life
to the use of one-third of the husband's real estate from his death.
It operates in favor of the wife and not in favor of the husband, and
is indefeasible by the husband's will or the husband's acts while
living, and does not depend upon the birth of a child by the marriage.
</p><p>
The order of distribution of the husband's personal property on his
death is as follows, viz.: 1st, the widow of a family takes articles
exempt from execution as hers, also $150 worth of property besides.
2d, she has one-third of the personal property, absolutely&mdash;if there
be no children, one-half, and if there be no parent or descendant, she
is entitled, of the residue, to $2,000, and if also no brother,
sister, nephew, or niece, all the residue. This order may be varied or
defeated by his will.
</p><p>
The order of distribution of the wife's personal property on her death
without will is as follows: It goes, after paying her debts, to her
husband, if living; if not, then 1st, to her children, 2d to her
father, 3d to her mother, 4th to her collateral relatives. This order
may be varied or defeated by her will. She may devise it as she may
please.
</p><p>
His property before marriage continues his after marriage, subject to
her inchoate rights of dower.
</p><p>
Her property before marriage continues hers absolutely.
</p><p>
Upon marriage he is liable to support her, and may be compelled to do
it if he prove refractory.
</p><p>
She is not liable to support him, however wealthy she may be, or poor
he may be.
</p><p>
He is liable to support the children. She is not so liable, though
possessed of millions.
</p><p>
The husband is the guardian of the wife, as against third persons.
(Page 488). But he has no power to preserve, retain, or regain the
custody of her against her will. (Page 47).
</p><p>
He may maintain his action against third persons for enticing her away
or harboring her. But this harboring, to be actionable, must be more
than a mere permission to her to stay with such third person. (4 Barb.
225).
</p><p>
If the husband seek to take away his wife by force, it is an assault
and battery upon her. If a third person, resists such force at her
request he is not liable to any action. (Barb. 156).
</p><p>
The wife is not the husband's guardian, but if he will desert her he
may be put under bonds for her support and the support of her children
by him. (2 Rev. Stat., 4th Ed., pp. 53, 54).
</p><p>
The husband is liable for the debts of the wife contracted before
marriage, but only now to the extent of her property received by him.
(7 W. R. 237, 1st Chitty Pl., 66 to 68, laws of 1853). And he is
liable for her debts contracted during marriage, if permitted by him,
or if for necessaries which he neglected to provide.
</p><p>
The wife is not liable for her husband's debts contracted at any time.
</p><p>
The law casts the custody of the minor children upon the father and
not upon the mother. But if this custody is abused, it is by the Court
to the mother.
</p><p>
The father may appoint a guardian for his infant children. (2 Rev.
Stat. 33.) But the Court will not allow such guardian to take the
children out of the State against the mother's will, much less to
separate them unjustly from the mother even though the father's will
command it. (5, page 596).
</p><p>
During the separation of husband and wife, it is for the court now to
decide, under the circumstances of each case, whether father or mother
has such custody. (2 R. S. 330, 332).
</p><p>
When both seek such custody, and both are equally qualified for it,
that of daughters and young children is usually given to the mother,
and that of the sons to the father, but this is in the discretion of
the Court.
</p><p>
The earnings of the husband are his. The earnings of the wife are his,
if she live with him and he support her.
</p><p>
But he can not compel her to work for him. And if she separate from
him for cause, he may be restrained for intermeddling with her
earnings.
</p><p>
The husband's abandonment and his refusal or neglect to provide for
her, are good causes of separation. (2 R. S. 329, sec. 53, sub. 3).
</p><p>
For the husband's torts the wife is not liable. For the wife's torts,
committed by her before marriage or during marriage the husband is
liable jointly with the wife. If committed by the wife and husband, or
committed by the wife in his presence and without objecting, the
husband is liable alone. (1 Chitty Pl., 105, 7th American edition).
Nay, even felonies (excepting murder, manslaughter, treason, and
robbery), are excusable in the wife if committed in the husband's
presence and by his coercion&mdash;and such coercion is presumed from his
presence. For this he must suffer and she must be spared. (Barb. Crim.
Law, 247 and 348, and cases there cited).
</p><p>
In actions or lawsuits between men and women, the law in theory claims
to be impartial, but in practice it has not been impartial. Before a
Court of male judges or a jury of men the bias is in favor of the
woman; and if she is pleasing, in person and manners, such bias is
sometimes pretty strong.
</p><p>
If the man and woman between whom litigation arises are husband and
wife, the Court may accord an allowance to be advanced by her husband,
to enable her to defray the expenses of the litigation.</p></div>

<div class="footnote"><p><a name="Footnote_125_125" id="Footnote_125_125"></a><a href="#FNanchor_125_125"><span class="label">[125]</span></a> <span class="smcap">Woman's Rights</span>.&mdash;<i>Circulate the Petitions</i>.&mdash;The design
of the Convention held last week in Rochester, was to bring the
subject of Woman's legal and civil disabilities, in a dignified form,
before the Legislature of New York. Convinced, as the friends of the
movement are, that in consistency with the principles of
Republicanism, females, equally with males, are entitled to Freedom,
Representation, and Suffrage, and confident as they are that woman's
influence will be found to be as refining and elevating in public as
all experience proves it to be in private, they claim that one-half of
the people and citizens of New York should no longer be governed by
the other half, without consent asked and given. Encouraged by reforms
already made, in the barbarous usages of common law, by the statutes
of New York, the advocates of woman's just and equal rights demand
that this work of reform be carried on, until every vestige of
partiality is removed. It is proposed, in a carefully prepared address
to specify the remaining legal disabilities from which the women of
this State suffer; and a hearing is asked before a joint committee of
both Houses, specially empowered to revise and amend the statutes. Now
is this movement right in principle? Is it wise in policy? Should the
females of New York be placed on a level of equality with males before
the law? If so, let us petition for impartial justice to Women. In
order to ensure this equal justice should the females of New York,
like the males, have a voice in appointing the law-makers and
law-administrators? If so let us petition for Woman's right to
Suffrage. Finally, what candid man will be opposed to a reference of
the whole subject to the Representatives of New York, whom the men of
New York themselves elected. Let us then petition for a hearing before
the Legislature. A word more, as to the petitions, given below. They
are two in number; one for the Just and Equal Rights of Woman; one for
Woman's Right to Suffrage. It is designed that they should be signed
by men and women, of lawful age&mdash;that is, of twenty-one years and
upwards. The following directions are suggested: 1. Let persons, ready
and willing, sign each of the petitions; but let not those, who desire
to secure Woman's Just and Equal Rights, hesitate to sign that
petition because they have doubts as to the right or expediency of
women's voting. The petitions will be kept separate, and offered
separately. All fair-minded persons, of either sex, ought to sign the
first petition. We trust that many thousands are prepared to sign the
second also. 2. In obtaining signatures, let men sign in one column,
and women in another parallel column. 3. Let the name of the town and
county, together with the number of signatures, be distinctly entered
on the petitions before they are returned. 4. Let every person, man or
woman, interested in this movement, instantly and energetically
circulate the petitions in their respective neighborhoods. We must
send in the name of every person in the State, who desires full
justice to woman, so far as it is possible. Up then, friends, and be
doing, to-day. 5. Let no person sign either petition but once. As many
persons will circulate petitions in the same town and county, it is
important to guard against this possible abuse. 6. Finally, let every
petition be returned to Rochester, directed to the Secretary of the
Convention, Susan B. Anthony, on the first of February, without fail.
In behalf of the Business Committee.
</p>
<p class="author">William Henry Channing.</p>
<p><span class="sc">Rochester</span>, <i>Dec. 8, 1853</i>.
</p><p>
<span class="smcap">Petition for the Just and Equal Rights of Women</span>.&mdash;The Legislature of
the State of New York have, by the Acts of 1848 and 1849, testified
the purpose of the people of this State to place married women on an
equality with married men, in regard to the holding, conveying, and
devising of real and personal property. We, therefore, the undersigned
petitioners, inhabitants of the State of New York, male and female,
having attained to the legal majority, believing that women, alike
married and single, do still suffer under many and grievous legal
disabilities, do earnestly request the Senate and Assembly of the
State of New York to appoint a Joint Committee of both Houses, to
revise the Statutes of New York, and to propose such amendments as
will fully establish the legal equality of women with men; and we
hereby ask a hearing before such Committee by our accredited
Representatives.
</p><p>
<span class="smcap">Petition for Woman's Right to Suffrage</span>.&mdash;Whereas, according to the
Declaration of our National Independence, governments derive their
just powers from the consent of the governed, we earnestly request the
Legislature of New York to propose to the people of the State such
amendments of the Constitution of the State as will secure to females
an equal right to the Elective Franchise with males; and we hereby ask
a hearing before the Legislature by our accredited Representatives.
</p><p>
N. B.&mdash;Editors throughout the State in favor of this movement are
respectfully requested to publish this address and the petitions.</p></div>

<div class="footnote"><p><a name="Footnote_126_126" id="Footnote_126_126"></a><a href="#FNanchor_126_126"><span class="label">[126]</span></a> <i>President</i>.&mdash;Elizabeth Cady Stanton.
</p><p>
<i>Vice-Presidents</i>.&mdash;Rev. S. J. May, Ernestine L. Rose, New York; Hon.
William Hay Saratoga; William H. Topp, Albany; Lydia A. Jenkins,
Geneva; Lydia Mott, Albany; Mary F. Love, Randolph.
</p><p>
<i>Business Committee</i>.&mdash;Rev. Antoinette L. Brown, South Butler; W. H.
Channing, Rochester; Mrs. Catherine A. F. Stebbins, Mrs. Phebe H.
Jones, Troy.
</p><p>
<i>Secretaries</i>.&mdash;Susan B. Anthony, Sarah Pellet.
</p><p>
<i>Finance Committee</i>.&mdash;Mary S. Anthony, Rochester; Anna W. Anthony,
Cayuga.</p></div>

<div class="footnote"><p><a name="Footnote_127_127" id="Footnote_127_127"></a><a href="#FNanchor_127_127"><span class="label">[127]</span></a> <span class="smcap">An Act Relative to the Rights of Married Women</span>:&mdash;<i>The
People of the State of New York, represented in Senate and Assembly,
do enact as follows</i>:
</p><p>
1. Any married woman whose husband, from drunkenness, profligacy, or
any other cause, shall neglect and refuse to provide for her support
and education, or the support and education of her children, and any
married woman who may be deserted by her husband, shall have the
right, by her own name, to receive and collect her own earnings, and
apply the same for her own support, and the support and education of
her children, free from the control and interference of her husband,
or from any person claiming to be released from the same by and
through her husband.
</p><p>
2. Hereafter it shall be necessary to the validity of any indenture of
apprenticeship executed by the father, that the mother of such child,
if she be living, shall, in writing, consent to such indentures; nor
shall any appointment of a general guardian of the person of a child
by the father be valid, unless the mother of such child, if she be
living, shall, in writing, consent to such appointment.</p></div>

<div class="footnote"><p><a name="Footnote_128_128" id="Footnote_128_128"></a><a href="#FNanchor_128_128"><span class="label">[128]</span></a> See Appendix.</p></div>

<div class="footnote"><p><a name="Footnote_129_129" id="Footnote_129_129"></a><a href="#FNanchor_129_129"><span class="label">[129]</span></a> Ernestine L. Rose, Francis D. Gage, Hannah Tracy
Cutler, Lucy N. Coleman, Antoinette L. Brown, Matilda Joslyn Gage,
Marietta Richmond, Sarah Pellet, Carrie D. Filkins, Lydia A. Jenkins,
Susan B. Anthony, dividing their time and forces, held conventions in
nearly every county of the State, traversing some new section each
year. In 1859, Miss Anthony and Miss Brown made a successful tour of
the fashionable resorts and the northern counties. All this work the
State Committee assigned to its General Agent, giving her all honor
and power, without providing one dollar. But Miss Anthony with rare
executive ability, accomplished the work and paid all expenses.&mdash;E. C.
S.</p></div>

<div class="footnote"><p><a name="Footnote_130_130" id="Footnote_130_130"></a><a href="#FNanchor_130_130"><span class="label">[130]</span></a> It is pleasant to record that a few years later Mr.
Beecher's vision was clear on the whole question, and he was often
found on the woman's rights platform, not only speaking himself, but
his sister, Mrs. Isabella Beecher Hooker, also. On one occasion he
conducted Miss Kate Field to the platform in Plymouth Church as
gracefully as he ever handed a lady out to dinner, introduced her to
the audience, and presided during her address. Sitting there he seemed
to feel as much at his ease as if Col. Robert G. Ingersoll had been
the speaker.</p></div>

<div class="footnote"><p><a name="Footnote_131_131" id="Footnote_131_131"></a><a href="#FNanchor_131_131"><span class="label">[131]</span></a> As this meeting was hastily decided upon, there was no
call issued; it was merely noticed in the county papers. <i>The Saratoga
Whig</i>, August 18, 1854, says:
</p><p>
<span class="smcap">Women's Rights</span>.&mdash;The series of conventions that have been holding
sessions in the village during the week, will close this day with a
meeting for the discussion of the social, legal, and political rights
of women, at which Miss Susan B. Anthony, Mrs. Matilda Joslyn Gage,
and Miss Sarah Pellet will appear. The meetings will be held at St.
Nicholas Hall this afternoon at 3 and a half o'clock, and in the
evening at 8 o'clock.</p></div>

<div class="footnote"><p><a name="Footnote_132_132" id="Footnote_132_132"></a><a href="#FNanchor_132_132"><span class="label">[132]</span></a> Any one but the indomitable Susan B. Anthony would have
abandoned all idea of a meeting, but, as it was advertised, she felt
bound to make it a fact. This decision may seem the more remarkable in
view of other facts, that Miss Anthony had but little experience as a
speaker, and was fully aware of her deficiencies in that line; her
forte lay in planning conventions, raising money, marshalling the
forces, and smoothing the paths for others to go forward, make the
speeches, and get the glory. Having listened in St. Nicholas Hall for
several days to some of the finest orators in the country, it was with
great trepidation that she resolved to attempt to hold such audiences
as had crowded all the meetings during the week, and would no doubt
continue to do so. However, she had one written speech, which she
decided to divide, giving the industrial disabilities of women in the
afternoon, and their political rights in the evening, supplementing
each with whatever extemporaneous observations might strike her mind
as she proceeded. With Mrs. Gage to speak at one session and Miss
Pellet at the other, Miss Anthony rounded out both meetings to the
general satisfaction. It was thus she always stood ready for every
emergency; when nobody else would or could speak she did; when
everybody wished to speak she was silent.&mdash;E. C. S.</p></div>

<div class="footnote"><p><a name="Footnote_133_133" id="Footnote_133_133"></a><a href="#FNanchor_133_133"><span class="label">[133]</span></a> <i>The Daily Saratogian</i>. August 19th, said: Mrs. Matilda
Joslyn Gage, a medium-sized, lady-like looking woman, dressed in a
tasty plum-colored silk with two flounces, made the first address upon
some of the defects in the marriage laws, quoting Story, Kent, and
Blackstone. She closed by speaking of Mrs. Marcet, an able writer on
political economy, her book much used in schools. She referred to Miss
Pinckney, of South Carolina, who in nullification times, wrote
powerfully on that subject. It was said that party was consolidated by
the nib of a lady's pen. She was the first woman in the United States
who was honored with a public funeral.</p></div>

<div class="footnote"><p><a name="Footnote_134_134" id="Footnote_134_134"></a><a href="#FNanchor_134_134"><span class="label">[134]</span></a> <i>President</i>.&mdash;Martha C. Wright, of Auburn.
</p><p>
<i>Vice-Presidents</i>.&mdash;Rev. Samuel J. May, Syracuse; Lydia Mott, Albany;
Ernestine L. Rose, New York; Antoinette L. Brown, New York; Susan B.
Anthony, Rochester; Augusta A. Wiggins, Saratoga Springs.
</p><p>
<i>Secretaries</i>.&mdash;Emily Jaques, Nassau; Aaron M. Powell, Ghent; Mary L.
Booth, Williamsburgh.
</p><p>
<i>Finance Committee</i>.&mdash;Susan B. Anthony, Marietta Richmond, Mary S.
Anthony, Phebe H. Jones.
</p><p>
<i>Business Committee</i>.&mdash;Antoinette L. Brown, Ernestine L. Rose, T. W.
Higginson, Charles F. Hovey, of Boston; Phebe Merritt, of Michigan;
Hon. William Hay, of Saratoga Springs.</p></div>

<div class="footnote"><p><a name="Footnote_135_135" id="Footnote_135_135"></a><a href="#FNanchor_135_135"><span class="label">[135]</span></a> Now the successful editor of <i>Harper's Bazar</i>.</p></div>

<div class="footnote"><p><a name="Footnote_136_136" id="Footnote_136_136"></a><a href="#FNanchor_136_136"><span class="label">[136]</span></a> This year Miss Anthony canvassed the State, holding
conventions in fifty-four counties, organizing societies, getting
signatures to petitions, and subscribers to <i>The Una</i>. At some of
these meetings Mrs. Rose, Miss Brown, and Miss Filkins assisted by
turn, but the chief part she carried through alone. She had posters
for the entire State printed in Rochester, her father, brother
Merritt, and Mary Luther folding and superscribing to all the
postmasters and the sheriff of every county. The sheriffs, with but
few exceptions, opened the Court Houses for the meetings, posted the
bills, and attended to the advertising. Miss Anthony entered on this
work without the pledge of a dollar. But with free meetings and
collections in the afternoon, and a shilling admission in the evening,
she managed to cover the entire expenses of the campaign.</p></div>

<div class="footnote"><p><a name="Footnote_137_137" id="Footnote_137_137"></a><a href="#FNanchor_137_137"><span class="label">[137]</span></a></p>
<p class="heading"><span class="smcap">Women's Rights Petition</span>.
</p><p>
<i>To the Honorable, the Senate and Assembly of the State of New York</i>:
</p><p>
<span class="smcap">Whereas</span>, the women of the State of New York are recognized as citizens
by the Constitution, and yet are disfranchised on account of sex; we
do respectfully demand the right of suffrage; a right which involves
all other rights of citizenship, and which can not be justly withheld,
when we consider the admitted principles of popular government, among
which are the following:
</p><p>
1st. That all men are born free and equal.
</p><p>
2d. That government derives its just powers from the consent of the
governed.
</p><p>
3d. That taxation and representation should go together.
</p><p>
4th. That those held amenable to laws should have a share in framing
them.
</p><p>
We do, therefore, petition that you will take the necessary steps so
to revise the Constitution of our State, as that all her citizens may
enjoy equal political privileges.</p></div>

<div class="footnote"><p><a name="Footnote_138_138" id="Footnote_138_138"></a><a href="#FNanchor_138_138"><span class="label">[138]</span></a> The committee were Susan B. Anthony, Ernestine L. Rose,
Antoinette L. Brown, Elizabeth Cady Stanton, Martha C. Wright, Lydia
Mott.</p></div>

<div class="footnote"><p><a name="Footnote_139_139" id="Footnote_139_139"></a><a href="#FNanchor_139_139"><span class="label">[139]</span></a> At the close of this Convention, Charles F. Hovey, as
was his usual custom, planned an excursion for those who had taken
part in the meetings. He invited them to take a drive to the lake, a
few miles out of Saratoga, gave them a bountiful repast, and together
they spent a day rich in pleasant memories. Listening day after day to
the wrongs perpetrated on woman by law and Gospel of man's creation,
Mr. Hovey always seemed to feel that he was in duty bound to throw
what sunshine and happiness he could into the lives of women, and thus
in a measure atone for the injustice of his sex, and most royally he
did this whenever an opportunity offered, not only while he lived, but
by bequests at his death.</p></div>

<div class="footnote"><p><a name="Footnote_140_140" id="Footnote_140_140"></a><a href="#FNanchor_140_140"><span class="label">[140]</span></a> Twenty years after this Mrs. Stanton met a lady in
Texas, who told her about this Saratoga Convention. She said her
attention was first called to the subject of woman's rights by some
tracts a friend of hers, then living in Georgia, brought home at that
time, and that we could form but little idea of the intense interest
with which they were read and discussed by quite a circle of ladies,
who plied her aunt with innumerable questions about the Convention and
the appearance and manners of the ladies who led the movement.</p></div>

<div class="footnote"><p><a name="Footnote_141_141" id="Footnote_141_141"></a><a href="#FNanchor_141_141"><span class="label">[141]</span></a> It is now over forty years that the various branches of
the Hutchinson family have been singing the liberal ideas of their day
on the anti-slavery, temperance, and Woman's Rights platforms, and
they are singing still (1881) with the infusion of some new blood in
the second and third generation. Only one year ago traveling in
Kansas, on a dreary night train, with no sleeping car attached, I had
worried through the weary hours until three o'clock in the morning,
when the cars stopped at Fort Scott. I was slowly pacing up and down
the aisle, when in came Asa Hutchinson, violin in hand, and a troop of
boys and girls behind him. There we stood face to face, both well on
the shady side of sixty-five, our locks as white as snow, each
thinking the other was too old for such hard journeys, he still
singing, I still preaching "equal rights to all." "Well," said I,
"Asa, this is a very unchristian hour for you to be skylarking over
the prairies of Kansas." "Ah!" said he, dolorously, "this is no
skylarking; we sung last night until near eleven o'clock, shook hands,
and talked until twelve; arose about two, waited an hour at a cold
depot, and we all feel as cross as bears." "I can sympathize with
you," I replied; "I spent the hours until twelve as you did,
entertaining my countrymen and women, and have been trying to rest
ever since." In talking over old times until the day dawned we forgot
our fatigue, and as I left the cars they gave me a parting salute with
the "good time coming." How well I remember the power of the young
Hutchinsons in the old mob days; four brothers and one sister standing
side by side on the platform in Faneuil Hall, Boston. So hated were
the Abolitionists and their doctrines, that not even Wendell Phillips
or Abby Kelly could get a hearing, but when the sweet singers from the
old Granite State came forward silence reigned, to be broken, however,
the moment the last notes of harmony died upon their lips. E. C. S.</p></div>

<div class="footnote"><p><a name="Footnote_142_142" id="Footnote_142_142"></a><a href="#FNanchor_142_142"><span class="label">[142]</span></a> Saratoga, Niagara, and Trenton Falls; Clifton, Avon,
Sharon, and Ballston Springs, Lake George, etc. In making the tour In
1859, Miss Brown and Miss Anthony had some recherch&eacute; out-door meetings
in the groves of Clifton and Trenton that were highly praised by the
press and the people, and in the long summer days most charming to
themselves.</p></div>

<div class="footnote"><p><a name="Footnote_143_143" id="Footnote_143_143"></a><a href="#FNanchor_143_143"><span class="label">[143]</span></a> The speakers were Samuel J. May, Ernestine L. Rose,
Antoinette L. Brown, Carrie D. Filkins, Lydia A. Jenkins, Aaron M.
