<div class="footnote"><p><a name="Footnote_144_144" id="Footnote_144_144"></a><a href="#FNanchor_144_144"><span class="label">[144]</span></a> If the intestate be a married man living, and having
lived with his wife daring marriage, or if the intestate be a married
woman living or having lived with her husband during marriage, and
shall die without lawful descendants, born or to be born of such
marriage, or a prior marriage, the inheritance shall descend to the
surviving husband or wife, as the case may be, during his or her
natural life, whether the inheritance came to the intestate on the
part of the mother or father or otherwise.</p></div>

