Prosser, Ramsey, Robertson, Rotch, Warner, Williams&mdash;21.</p></div>

<div class="footnote"><p><a name="Footnote_163_163" id="Footnote_163_163"></a><a href="#FNanchor_163_163"><span class="label">[163]</span></a> <i>President.</i>&mdash;Martha Wright, of Auburn, New York.
</p><p>
<i>Vice-Presidents.</i>&mdash;Abby Hopper Gibbons, of New York; Asa Fairbanks,
